 "path": "/notifications",
 "method": "GET",
 "description": "Get a list of your notifications.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "read",
   "type": "boolean",
   "required": false,
   "description": "Filter notifications by read status. Will skip filtering if not passed.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "notification_id": 1,
    "type": "expense_added",
    "title": "string",
    "message": "string",
    "read": true,
    "created_at": "2019-01-01T00:00:00",
    "data": {}
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

